insert into public.cartes(id,num,titre,description,matiere,famille,rarete,contenu,anecdote,serie,image,actif) values
('cx-e1-001',1001,'Fer de faille','Une veine claire traverse la pierre sans suivre aucune cassure.','divers','mineraux','commune','Une veine claire traverse la pierre sans suivre aucune cassure.','Le métal semble s’être déposé avant la roche. Je préfère recommencer les mesures avant de tirer une conclusion embarrassante.','cortex-e1','assets/cartes/cortex/edition-i-24/fer-de-faille.webp',false),
('cx-e1-002',1002,'Clé bifide','Deux tiges entrelacées. Aucune serrure correspondante n’a encore été retrouvée.','divers','vestiges','epique','Deux tiges entrelacées. Aucune serrure correspondante n’a encore été retrouvée.','Une seule clé, deux serrures ? Ou deux clés qui refusent de se séparer ? Ne pas tenter de les redresser.','cortex-e1','assets/cartes/cortex/edition-i-24/cle-bifide.webp',false),
('cx-e1-003',1003,'Lentille des échos','Un croissant demeure visible dans le verre, quelle que soit la lumière.','divers','instruments','epique','Un croissant demeure visible dans le verre, quelle que soit la lumière.','La lentille ne grossit rien. Elle montre pourtant quelque chose. Il reste à déterminer où ce quelque chose se trouve.','cortex-e1','assets/cartes/cortex/edition-i-24/lentille-des-echos.webp',false),
('cx-e1-004',1004,'Graine d’orage','Sous ses deux enveloppes, une tempête semble attendre son heure.','divers','specimens','epique','Sous ses deux enveloppes, une tempête semble attendre son heure.','Aucun signe de germination. Plusieurs signes d’orage. Par précaution, j’ai éloigné l’arrosoir.','cortex-e1','assets/cartes/cortex/edition-i-24/graine-d-orage.webp',false),
('cx-e1-005',1005,'Cœur de braise','Une lumière brûlante circule au cœur du cristal sans jamais se consumer.','divers','mineraux','legendaire','Une lumière brûlante circule au cœur du cristal sans jamais se consumer.','La température des instruments ne varie pas. Les instruments, en revanche, ont tous été déplacés pendant la nuit.','cortex-e1','assets/cartes/cortex/edition-i-24/coeur-de-braise.webp',false),
('cx-e1-006',1006,'Sceau du Néant','Les fragments retiennent une ouverture dont on ne voit pas l’autre côté.','divers','vestiges','mythique','Les fragments retiennent une ouverture dont on ne voit pas l’autre côté.','Je ne sais pas ce que ce sceau ferme. C’est précisément la raison pour laquelle personne ne doit tenter de l’ouvrir.','cortex-e1','assets/cartes/cortex/edition-i-24/sceau-du-neant.webp',false),
('cx-e1-007',1007,'Quartz sourd','Ses bandes opaques semblent retenir la lumière au lieu de la réfléchir.','divers','mineraux','peu_commune','Ses bandes opaques semblent retenir la lumière au lieu de la réfléchir.','Trois cristaux, trois mesures différentes. Aucun n’apprécie que l’on frappe sur la table.','cortex-e1','assets/cartes/cortex/edition-i-24/quartz-sourd.webp',false),
('cx-e1-008',1008,'Verre de faille','Une ligne claire demeure suspendue dans cet éclat de verre fumé.','divers','mineraux','rare','Une ligne claire demeure suspendue dans cet éclat de verre fumé.','La cassure contourne la ligne sans jamais la traverser. Je conserve les deux observations séparément.','cortex-e1','assets/cartes/cortex/edition-i-24/verre-de-faille.webp',false),
('cx-e1-009',1009,'Vesperite','Une couture lavande réunit les lames de ce minéral vert profond.','divers','mineraux','epique','Une couture lavande réunit les lames de ce minéral vert profond.','Les lames paraissent pousser dans plusieurs directions à la fois. L’étagère n’a rien demandé.','cortex-e1','assets/cartes/cortex/edition-i-24/vesperite.webp',false),
('cx-e1-010',1010,'Nacre de nuit','Sous ses couches sombres, une lumière cyan ne trouve aucune sortie.','divers','mineraux','mythique','Sous ses couches sombres, une lumière cyan ne trouve aucune sortie.','La lumière apparaît entre les lames, jamais à leur surface. Éviter de chercher avec un marteau.','cortex-e1','assets/cartes/cortex/edition-i-24/nacre-de-nuit.webp',false),
('cx-e1-011',1011,'Aiguille de dérive','L’aiguille reste en équilibre, même lorsque son support est déplacé.','divers','instruments','legendaire','L’aiguille reste en équilibre, même lorsque son support est déplacé.','Elle indique une direction. Je n’ai pas encore trouvé de carte où cette direction soit utile.','cortex-e1','assets/cartes/cortex/edition-i-24/aiguille-de-derive.webp',false),
('cx-e1-012',1012,'Compas décentré','Ses deux branches inégales tracent des courbes étonnamment régulières.','divers','instruments','commune','Ses deux branches inégales tracent des courbes étonnamment régulières.','Son concepteur ne cherchait manifestement pas le centre. Cela ne l’a pas empêché de le trouver.','cortex-e1','assets/cartes/cortex/edition-i-24/compas-decentre.webp',false),
('cx-e1-013',1013,'Diapason muet','La traverse de verre frémit sans qu’aucun son ne soit perceptible.','divers','instruments','rare','La traverse de verre frémit sans qu’aucun son ne soit perceptible.','Le silence n’est pas une mesure suffisante. Mes collègues soutiennent le contraire depuis une heure.','cortex-e1','assets/cartes/cortex/edition-i-24/diapason-muet.webp',false),
('cx-e1-014',1014,'Pince d’équilibre','Les pointes de céramique maintiennent un écart que rien ne semble réduire.','divers','instruments','peu_commune','Les pointes de céramique maintiennent un écart que rien ne semble réduire.','Elle saisit très bien les objets fragiles. Elle refuse seulement de les toucher.','cortex-e1','assets/cartes/cortex/edition-i-24/pince-d-equilibre.webp',false),
('cx-e1-015',1015,'Astrolabe des marées','Une courbe lumineuse traverse l’eau suspendue entre ses arcs.','divers','instruments','mythique','Une courbe lumineuse traverse l’eau suspendue entre ses arcs.','Il suit une marée. La difficulté sera de retrouver la mer correspondante.','cortex-e1','assets/cartes/cortex/edition-i-24/astrolabe-des-marees.webp',false),
('cx-e1-016',1016,'Sceau fendu','Sa marque circulaire se poursuit de part et d’autre d’une vieille fente.','divers','vestiges','commune','Sa marque circulaire se poursuit de part et d’autre d’une vieille fente.','Les empreintes restent complètes malgré la fissure. J’ai vérifié le papier avant d’accuser le sceau.','cortex-e1','assets/cartes/cortex/edition-i-24/sceau-fendu.webp',false),
('cx-e1-017',1017,'Jeton sans face','Deux ouvertures remplacent les faces de ce lourd jeton.','divers','vestiges','peu_commune','Deux ouvertures remplacent les faces de ce lourd jeton.','Ni valeur, ni portrait, ni inscription. Il a pourtant été soigneusement conservé par quelqu’un.','cortex-e1','assets/cartes/cortex/edition-i-24/jeton-sans-face.webp',false),
('cx-e1-018',1018,'Disque des passages','Trois chemins de métal s’arrêtent au bord d’une même fente lumineuse.','divers','vestiges','rare','Trois chemins de métal s’arrêtent au bord d’une même fente lumineuse.','Aucun chemin ne rejoint le bord du disque. Il manque peut-être une destination, plutôt qu’un morceau.','cortex-e1','assets/cartes/cortex/edition-i-24/disque-des-passages.webp',false),
('cx-e1-019',1019,'Clé des seuils','Une déchirure ambrée relie les parties séparées de cette clé.','divers','vestiges','legendaire','Une déchirure ambrée relie les parties séparées de cette clé.','Je n’ai trouvé aucune serrure. Je commence à soupçonner que la clé n’en a pas besoin.','cortex-e1','assets/cartes/cortex/edition-i-24/cle-des-seuils.webp',false),
('cx-e1-020',1020,'Coquille inverse','Sa spirale change de sens avant de rejoindre l’ouverture.','divers','specimens','commune','Sa spirale change de sens avant de rejoindre l’ouverture.','Son ancien occupant disposait de beaucoup d’espace et d’un sens de l’orientation particulier.','cortex-e1','assets/cartes/cortex/edition-i-24/coquille-inverse.webp',false),
('cx-e1-021',1021,'Graine de brume','Une brume pâle tourne lentement sous l’enveloppe translucide.','divers','specimens','peu_commune','Une brume pâle tourne lentement sous l’enveloppe translucide.','Deux feuilles, aucune racine visible. La cloche sert surtout à rassurer l’assistant.','cortex-e1','assets/cartes/cortex/edition-i-24/graine-de-brume.webp',false),
('cx-e1-022',1022,'Spore de verre','De fins filaments relient trois membranes presque transparentes.','divers','specimens','rare','De fins filaments relient trois membranes presque transparentes.','Le verre serait une explication commode. Malheureusement, le spécimen continue de pousser.','cortex-e1','assets/cartes/cortex/edition-i-24/spore-de-verre.webp',false),
('cx-e1-023',1023,'Fleur de veille','Ses pétales sombres se referment autour d’un cœur laiteux.','divers','specimens','mythique','Ses pétales sombres se referment autour d’un cœur laiteux.','Elle se tourne vers les lampes éteintes. Je lui ai réservé celle qui fonctionne le moins bien.','cortex-e1','assets/cartes/cortex/edition-i-24/fleur-de-veille.webp',false),
('cx-e1-024',1024,'Cocon d’aurore','Une lumière chaude passe sous les fibres vert d’eau de sa soie.','divers','specimens','legendaire','Une lumière chaude passe sous les fibres vert d’eau de sa soie.','Le cocon est immobile. Son ombre, elle, donne parfois l’impression d’attendre quelque chose.','cortex-e1','assets/cartes/cortex/edition-i-24/cocon-d-aurore.webp',false)
